import sys,pathlib,json,hashlib,subprocess
r=pathlib.Path(sys.argv[1]);content=pathlib.Path(sys.argv[2]).read_text();out=pathlib.Path(sys.argv[3]);path='.bstack/assessment.json';rev=subprocess.check_output(['git','-C',str(r),'rev-parse','HEAD'],text=True).strip()
h=lambda b:hashlib.sha256(b).hexdigest();digest=lambda o:h(json.dumps(o,sort_keys=True,separators=(',',':')).encode())
