p={'schemaVersion':1,'target':f['target'],'findings':str(fp),'findingsDigest':digest(f),'selectedFindingIds':['F-001'],'reviewedScope':[{'path':path,'resolvedPath':str(r/path)}],'edits':[{'id':'assessment','findingId':'F-001','path':path,'originalHash':h((r/path).read_bytes()) if (r/path).exists() else None,'proposedHash':h(content.encode()),'operation':'replace-file' if (r/path).exists() else 'create','payload':{'content':content},'proposedContent':content}]};p['planDigest']=digest(p);out.write_text(json.dumps(p,indent=2)+'\n')
